"""Coordinate Laplacians and the source's general exterior-sphere problem."""
def populate(add,C,M,table):
    add(18,'Laplace equation(라플라스 방정식) · 좌표계 선택',[
      C('같은 연산자도 좌표에 따라 모양이 달라집니다.', M(r'\nabla^2u=0'), table(['좌표계','변수의 뜻','라플라스 연산자'],[
        ('Cartesian(직교)','x,y,z: 세 직선 좌표',M(r'\nabla^2u=u_{xx}+u_{yy}+u_{zz}')),
        ('Cylindrical(원통)','r: z축까지 거리, θ: 방위각, z: 높이',M(r'\nabla^2u=u_{rr}+\frac1ru_r+\frac1{r^2}u_{\theta\theta}+u_{zz}')),
        ('Spherical(구면)','r: 원점까지 거리, θ: 방위각, φ: +z축에서 잰 극각',M(r'\nabla^2u=\frac1{r^2}\left[\frac{\partial}{\partial r}(r^2u_r)+\frac1{\sin\phi}\frac{\partial}{\partial\phi}(\sin\phi\,u_\phi)+\frac1{\sin^2\phi}u_{\theta\theta}\right]'))]), '각도 이름은 원본을 따릅니다. 일부 교재는 θ와 φ의 이름을 반대로 사용하므로 기호보다 각도를 잰 방향을 확인합니다. 원본 구면 식의 1/r²는 대괄호 전체에 곱해져 있으며 올바른 식입니다.'),
      C('물리적 가정과 대칭을 구별합니다.', 'Laplace equation(라플라스 방정식)은 열원 없는 균일 매질의 정상 열전도, 전하 없는 영역의 정전기 퍼텐셜, 비압축·비회전 유동의 속도퍼텐셜 등에서 등장합니다. 모든 열·전기·유동 문제가 자동으로 이 식을 따르는 것은 아닙니다.', M(r'\text{axisymmetric: }u_\theta=0;\qquad\text{spherically symmetric: }u_\theta=u_\phi=0'), '다음 원본 문제는 axisymmetric(축대칭)이어서 θ 항만 없어집니다. φ에 따른 표면 데이터가 있으므로 구면대칭으로 줄일 수 없습니다. 원통 r과 구면 r도 서로 다른 거리입니다.')
    ],[
      C('1 · 경계를 간단하게 쓰려고 좌표를 바꿉니다.', '네모 경계에는 x,y,z가, 원통에는 축까지 거리 r과 높이 z가, 구에는 중심까지 거리 r이 편리합니다. Laplace equation(라플라스 방정식) ∇²u=0은 같지만 좌표를 바꾸면 거리와 면적의 변화가 미분식에 반영됩니다.', M(r'\text{Cartesian: }u_{xx}+u_{yy}+u_{zz}=0'), M(r'\text{Cylindrical: }u_{rr}+\frac1ru_r+\frac1{r^2}u_{\theta\theta}+u_{zz}=0'), '원형 막의 극좌표 식에 높이 방향의 uzz가 추가되면 원통좌표 식입니다. 구면좌표에서는 높이 z 대신 위아래 방향의 각도를 씁니다.'),
      C('2 · 원본의 두 각도를 먼저 고정합니다.', 'Spherical coordinates(구면좌표)에서 r은 원점부터의 거리, θ는 z축 주위를 도는 방위각, φ는 +z축에서 아래로 잰 극각입니다. 북극은 φ=0, 적도는 π/2, 남극은 π입니다.', M(r'x=r\sin\phi\cos\theta,\quad y=r\sin\phi\sin\theta,\quad z=r\cos\phi'), '교재마다 두 각도 문자를 바꿔 쓰기도 합니다. 이번 노트는 원본과 같은 규약을 계속 사용합니다.'),
      C('3 · 대괄호 전체에 1/r²가 곱해집니다.', M(r'\nabla^2u=\frac1{r^2}\left[(r^2u_r)_r+\frac{(\sin\phi\,u_\phi)_\phi}{\sin\phi}+\frac{u_{\theta\theta}}{\sin^2\phi}\right]'), M(r'\frac1{r^2}(r^2u_r)_r=u_{rr}+\frac2ru_r'), '곱의 미분으로 r²를 미분하면 2r이 나와 2uᵣ/r 항이 생깁니다. φ와 θ 항에도 바깥의 1/r²가 곱해진다는 점을 놓치지 마십시오. 원본 식을 고칠 부분이 아니라 괄호를 정확히 읽을 부분입니다.'),
      C('4 · 축대칭과 구면대칭은 조건이 다릅니다.', 'Axisymmetric(축대칭)은 z축 둘레로 돌려도 같다는 뜻이라 θ가 없어집니다. 북극과 적도의 값은 달라도 됩니다. Spherical symmetry(구면대칭)는 방향을 어떻게 바꾸어도 같아 φ까지 없어지는 더 강한 조건입니다.', M(r'\text{축대칭: }u=u(r,\phi),\qquad\text{구면대칭: }u=u(r)'), '다음 슬라이드에서 u(R,φ)=f(φ)이므로 극각에 따른 변화가 남습니다. 시간 t는 없으며, 초기조건이 아닌 구 표면의 boundary data(경계 데이터)를 맞추는 문제입니다.')
    ])

    add(19,'원본 문제 · 구 바깥의 축대칭 라플라스 방정식',[
      C('문제의 영역과 경계조건', M(r'r>R,\quad\nabla^2u=0,\quad u(R,\phi)=f(\phi),\quad\lim_{r\to\infty}u(r,\phi)=0'), 'θ에 무관한 exterior problem(외부 영역 문제)입니다. 0≤φ≤π에서 극점이 정칙인 해를 구합니다. f의 구체적인 식은 원본에 없으므로 일반 f의 계수 적분으로 풀이를 완성합니다. 원점은 영역 밖이므로 r=0에서의 유한성을 요구하지 않습니다.'),
      C('1 · 반지름과 극각을 분리합니다.', M(r'(r^2u_r)_r+\frac1{\sin\phi}(\sin\phi\,u_\phi)_\phi=0'), M(r'u=S(r)P(\phi)\quad\Rightarrow\quad\frac{(r^2S^\prime)^\prime}{S}=-\frac{(\sin\phi P^\prime)^\prime}{P\sin\phi}=\ell(\ell+1)'), M(r'r^2S^{\prime\prime}+2rS^\prime-\ell(\ell+1)S=0,\quad\frac{(\sin\phi P^\prime)^\prime}{\sin\phi}+\ell(\ell+1)P=0'), '상수를 ℓ(ℓ+1)로 쓴 이유는 양 극점에서 정칙인 각도 고유문제의 허용값이 이 형태이기 때문입니다. 아래에서 ℓ=0,1,2,…의 Legendre polynomial(르장드르 다항식)을 사용합니다.'),
      C('2 · z=cosφ로 르장드르 방정식을 얻습니다.', M(r'P(\phi)=V(z),\quad z=\cos\phi,\quad P^\prime=-\sin\phi V^\prime,\quad P^{\prime\prime}=-\cos\phi V^\prime+\sin^2\phi V^{\prime\prime}'), M(r'P^{\prime\prime}+\cot\phi P^\prime=(1-z^2)V^{\prime\prime}-2zV^\prime'), M(r'(1-z^2)V^{\prime\prime}-2zV^\prime+\ell(\ell+1)V=0,\qquad V=P_\ell(z)'), '양 극점 z=±1에서 정칙인 해는 정수 ℓ의 Pℓ입니다. 로그 특이성을 갖는 Qℓ는 제외합니다. P₀=1,P₁=z,P₂=(3z²−1)/2이며 이번에는 상수 성분이 허용되어 ℓ=0부터 시작합니다. 여기서 치환변수 z는 앞 슬라이드의 직교좌표 z와 다른 보조변수입니다.'),
      C('3 · Euler(오일러) 방정식의 거듭제곱 해', M(r'S=r^p\quad\Rightarrow\quad p(p-1)+2p-\ell(\ell+1)=0'), M(r'(p-\ell)(p+\ell+1)=0\quad\Rightarrow\quad S=C_\ell r^\ell+D_\ell r^{-\ell-1}'), '무한대에서 0이어야 하므로 증가하는 rℓ를 제외합니다. ℓ=0의 r⁰도 상수여서 제외되지만 1/r은 남습니다. 표면 r=R에서 인자가 1이 되도록 남은 해를 (R/r)ℓ⁺¹로 정규화합니다.'),
      C('4 · 표면 데이터를 르장드르 급수로 전개합니다.', M(r'f(\phi)=\sum_{\ell=0}^{\infty}a_\ell P_\ell(\cos\phi),\qquad\int_{-1}^1P_\ell(z)P_j(z)\,dz=\frac{2}{2\ell+1}\delta_{\ell j}'), M(r'\boxed{a_\ell=\frac{2\ell+1}{2}\int_0^\pi f(\phi)P_\ell(\cos\phi)\sin\phi\,d\phi}'), M(r'a_\ell=\frac{2\ell+1}{2}\int_{-1}^1 f(\arccos z)P_\ell(z)\,dz'), 'φ에서 z로 바꾸면 dz=−sinφ dφ이고 구간은 1→−1이어서 부호와 순서가 함께 바뀝니다. 정규화는 <a href="https://dlmf.nist.gov/14.17.E6">NIST DLMF 14.17.6</a>의 order=0 경우입니다. 적분의 가중치 sinφ를 빠뜨리지 않습니다.'),
      C('5 · 원본 일반 문제의 최종 해와 검산', M(r'\boxed{u(r,\phi)=\sum_{\ell=0}^{\infty}a_\ell\left(\frac Rr\right)^{\ell+1}P_\ell(\cos\phi),\qquad r\ge R}'), 'r=R에서는 반지름 인자가 1이므로 표면 급수가 f를 맞춥니다. 모든 반지름 인자는 무한대에서 0으로 가며, 각 모드의 반지름·각도 항은 ±ℓ(ℓ+1)로 상쇄됩니다. 매끄러운 표면 데이터에 대해 경계값과 수렴을 해석하고, 일반 L² 데이터에서는 경계 급수를 L² 의미로 봅니다. 구 내부 해의 (r/R)ℓ를 쓰면 이 외부 문제의 무한대 조건을 만족하지 못합니다.')
    ],[
      C('1 · 이번에는 시간이 아니라 바깥 공간의 값을 구합니다.', '반지름 R인 구의 표면에 f(φ)를 주고, 그 바깥 r>R의 u를 구합니다. 멀리 떨어질수록 u는 0이 되어야 합니다. Axisymmetric(축대칭)이므로 z축 둘레의 방향 θ는 같아도 북쪽·남쪽 φ에 따라 값이 달라질 수 있습니다.', M(r'u(R,\phi)=f(\phi),\qquad u\to0\quad(r\to\infty)'), '원본이 f를 구체적인 식으로 주지 않았기 때문에 특정 숫자 답은 정할 수 없습니다. 그렇다고 풀이가 끝나지 않는 것은 아닙니다. 어떤 f든 넣을 수 있는 계수 공식까지 구하는 것이 이 원본 문제의 답입니다.'),
      C('2 · 거리 변화와 각도 변화를 곱으로 시도합니다.', 'u=S(r)P(φ)를 대입합니다. θ 항은 축대칭으로 0이고, 남은 식의 바깥 1/r²를 없애려고 양변에 r²를 곱합니다.', M(r'P(r^2S^\prime)^\prime+\frac{S}{\sin\phi}(\sin\phi P^\prime)^\prime=0'), M(r'\frac{(r^2S^\prime)^\prime}{S}=-\frac{(\sin\phi P^\prime)^\prime}{P\sin\phi}=\ell(\ell+1)'), '왼쪽은 r만, 오른쪽은 φ만의 함수라 같은 상수여야 합니다. 그 상수를 ℓ(ℓ+1)로 쓰는 것은 나중에 각도 조건이 허용하는 값에 맞춘 표기입니다. 아직 이 시점에서 아무 실수 ℓ나 허용한다는 뜻은 아닙니다.'),
      C('3 · 각도 식에서 삼각함수를 정리합니다.', '곱의 미분을 펼치면 (sinφ P′)′=cosφ P′+sinφ P″입니다. 이를 sinφ로 나눕니다.', M(r'P^{\prime\prime}+\frac{\cos\phi}{\sin\phi}P^\prime+\ell(\ell+1)P=0'), 'z=cosφ라 두면 sin²φ=1−z²가 되어 삼각함수가 다항식으로 정리됩니다. 이 z는 계산용 보조변수로, 앞의 높이 좌표 z와는 별개입니다. P(φ)=V(z)라고 씁니다.', M(r'\frac{dz}{d\phi}=-\sin\phi,\quad P^\prime=-\sin\phi V^\prime'), M(r'P^{\prime\prime}=-\cos\phi V^\prime+\sin^2\phi V^{\prime\prime},\quad\frac{\cos\phi}{\sin\phi}P^\prime=-\cos\phi V^\prime'), 'V′ 항이 두 번 나와 −2cosφ V′가 됩니다. 마지막으로 cosφ=z,sin²φ=1−z²를 넣습니다.', M(r'(1-z^2)V^{\prime\prime}-2zV^\prime+\ell(\ell+1)V=0')),
      C('4 · 양 극점에서 정상인 각도 함수를 고릅니다.', '이 식이 Legendre equation(르장드르 방정식)입니다. 북극·남극에서 발산하지 않는 매끄러운 축대칭 모드를 고르면 ℓ=0,1,2,…가 되고 Legendre polynomial(르장드르 다항식) Pℓ가 나옵니다.', M(r'P_0(z)=1,\quad P_1(z)=z,\quad P_2(z)=\frac{3z^2-1}{2}'), 'P₀는 모든 각도에서 같은 성분이고, P₁은 북쪽과 남쪽 부호가 다른 성분입니다. 두 번째 독립해 Qℓ는 극점에서 특이하므로 제외합니다. 원형 막의 Bessel function(베셀 함수)와 구면의 Legendre polynomial(르장드르 다항식)은 서로 다른 공간 ODE에서 나온 도구입니다.'),
      C('5 · 반지름 식은 거듭제곱을 넣으면 풀립니다.', M(r'r^2S^{\prime\prime}+2rS^\prime-\ell(\ell+1)S=0'), 'r로 한 번 미분하면 거듭제곱 차수가 1 줄고, r을 곱하면 다시 돌아옵니다. 그래서 S=rᵖ를 시도하면 모든 항이 rᵖ로 모입니다.', M(r'S^\prime=pr^{p-1},\quad S^{\prime\prime}=p(p-1)r^{p-2}'), M(r'[p(p-1)+2p-\ell(\ell+1)]r^p=0'), M(r'p^2+p-\ell(\ell+1)=(p-\ell)(p+\ell+1)=0'), '따라서 p=ℓ 또는 p=−ℓ−1입니다. 거리 함수는 rℓ와 1/rℓ⁺¹의 합이 됩니다.'),
      C('6 · 바깥 문제이므로 멀리서 줄어드는 쪽을 고릅니다.', M(r'S=C_\ell r^\ell+D_\ell r^{-\ell-1}\quad\longrightarrow\quad D_\ell r^{-\ell-1}'), 'ℓ≥1이면 rℓ가 무한히 커지고, ℓ=0이면 1이 되어 0으로 가지 않습니다. 둘 다 제외합니다. 반면 1/rℓ⁺¹은 모두 0으로 갑니다. 원점에서 발산한다는 이유로 이를 버리면 안 됩니다. 우리가 푸는 영역은 r≥R>0이라 원점이 포함되지 않습니다.', M(r'\left(\frac Rr\right)^{\ell+1}\bigg|_{r=R}=1'), '상수 Rℓ⁺¹은 진폭 계수에 합칠 수 있으므로 이 형태로 정리합니다. 이제 표면에서는 반지름 부분이 1이 되어 각도 함수의 배합비만 정하면 됩니다.'),
      C('7 · 직교성을 이용해 표면 데이터의 계수를 구합니다.', M(r'f(\phi)=\sum_{\ell\ge0}a_\ell P_\ell(\cos\phi)'), '치환변수 z=cosφ로 보면 구간은 −1≤z≤1입니다. 서로 다른 Legendre polynomial(르장드르 다항식)의 곱 적분은 0이고, 같은 번호의 제곱 적분은 2/(2ℓ+1)입니다. 따라서 원하는 다항식을 곱해 적분하고 그 노름으로 나눕니다.', M(r'a_\ell=\frac{2\ell+1}{2}\int_{-1}^{1}f(\arccos z)P_\ell(z)\,dz'), '각도 φ로 되돌리면 z=−1은 φ=π, z=1은 φ=0입니다. dz의 빼기와 뒤집힌 적분 구간이 서로 상쇄됩니다.', M(r'\int_{-1}^1 f(\arccos z)P_\ell(z)\,dz=\int_{\pi}^0 f(\phi)P_\ell(\cos\phi)(-\sin\phi)\,d\phi'), M(r'\boxed{a_\ell=\frac{2\ell+1}{2}\int_0^\pi f(\phi)P_\ell(\cos\phi)\sin\phi\,d\phi}'), 'sinφ는 치환에서 나온 인자입니다. 구 표면의 위도 고리 면적이 sinφ에 비례한다는 기하적 의미도 있습니다. 이 인자를 빼면 다른 계수를 계산하게 됩니다.'),
      C('8 · 답을 조립하고 세 조건에 대입합니다.', M(r'\boxed{u(r,\phi)=\sum_{\ell=0}^{\infty}a_\ell\left(\frac Rr\right)^{\ell+1}P_\ell(\cos\phi)}'), '첫째, r=R이면 계수를 구할 때 맞춘 f가 됩니다. 둘째, r이 커지면 각 거리 인자가 0으로 줄어듭니다. 셋째, 각 모드의 거리 미분은 +ℓ(ℓ+1), 각도 미분은 −ℓ(ℓ+1)배가 되어 PDE에서 서로 지워집니다. 부드러운 f에서는 해당 경계 급수로 값을 해석하고, 덜 매끄러운 데이터에는 수렴의 의미를 따로 확인합니다.', '핵심은 변수분리 → 극점 정칙성 → 무한대 조건 → 표면 계수입니다. 기존 Fourier series(푸리에 급수)에서 배운 “맞는 부품을 고르고 직교성으로 배합비를 찾는다”는 흐름이 그대로 이어집니다.')
    ],role='원본 일반 문제 · 상세 완성 풀이')
